BORRAR = ["componentes_plataforma/central_panel.py", "componentes_plataforma/chat_agente.py", "componentes_plataforma/copytrading_panel.py", "componentes_plataforma/datos_mercado.py", "componentes_plataforma/diario_panel.py", "componentes_plataforma/favoritos_barra.py", "componentes_plataforma/flujo_vivo.py", "componentes_plataforma/iconos.py", "componentes_plataforma/inicio_panel.py", "componentes_plataforma/lista_activos_panel.py", "componentes_plataforma/mercados_panel.py", "componentes_plataforma/navegacion_superior.py", "componentes_plataforma/noticias_panel.py", "componentes_plataforma/panel_ordenes.py", "componentes_plataforma/panel_riel.py", "componentes_plataforma/posiciones_grafico.py", "componentes_plataforma/profundidad_panel.py", "componentes_plataforma/resumen_panel.py", "componentes_plataforma/un_clic.py"]
ZIP_B64 = ""


def norm(b):
    return b.replace(b"\r\n", b"\n")


def sha(f):
    """Hash del archivo (sin distinguir saltos de línea de Windows) o None si no existe."""
    return hashlib.sha256(norm(open(f, "rb").read())).hexdigest() if os.path.exists(f) else None


def main():
    z = zipfile.ZipFile(io.BytesIO(base64.b64decode(ZIP_B64)))
    nuevos = {f: norm(z.read(f)) for f in ARCHIVOS}
    destino = {f: hashlib.sha256(nuevos[f]).hexdigest() for f in ARCHIVOS}
    pendientes = [f for f in ARCHIVOS if sha(f) != destino[f]]
    a_borrar = [f for f in BORRAR if os.path.exists(f)]
    if not pendientes and not a_borrar:
        print("Ya estaba instalado: no hay nada que hacer.")
        return
    problemas = [f + (" ya existe con otro contenido" if sha(f) else " falta") + " o difiere de las versiones conocidas (¿cambios sin subir?)"
                 for f in pendientes if sha(f) not in ACEPTADAS[f]]
    if problemas:
        print("No se instaló nada:")
        for p in problemas:
            print("  -", p)
        sys.exit(1)
    for f in pendientes:
        datos = nuevos[f]
        os.makedirs(os.path.dirname(f) or ".", exist_ok=True)
        if os.path.exists(f) and b"\r\n" in open(f, "rb").read():
            datos = datos.replace(b"\n", b"\r\n")
        with open(f, "wb") as fh:
            fh.write(datos)
    for f in a_borrar:
        os.remove(f)
    print("Listo: %d archivos actualizados, %d eliminados." % (len(pendientes), len(a_borrar)))


if __name__ == "__main__":
    main()
